<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {NAlert,NButton,NIcon,NProgress,NTag} from 'naive-ui'
import {ArrowRight,ChartBar,Link,Receipt,Server,Users,Wallet,Calendar,Package} from '@vicons/tabler'
import {api,bytes} from '../api'
import {cycleStamp} from '../featureState'
const props=defineProps<{me:any;zone:string}>(),emit=defineEmits<{navigate:[string]}>()
const plan=ref<any>(null),error=ref('')
const remaining=computed(()=>Math.max(Number(props.me.quota_bytes)-Number(props.me.used_bytes),0))
const percentage=computed(()=>props.me.quota_bytes?Math.max(0,Math.min(Number(props.me.used_bytes)/Number(props.me.quota_bytes)*100,100)):0)
const expired=computed(()=>props.me.expires_at&&Date.parse(props.me.expires_at)<=Date.now())
const shortcuts=[{key:'subscription',title:'我的订阅',text:'获取客户端订阅链接',icon:Link},{key:'connectivity',title:'节点在线情况',text:'查看节点运行状态',icon:Server},{key:'usage',title:'流量明细',text:'查看流量使用记录',icon:ChartBar},{key:'invite',title:'邀请好友',text:'分享专属邀请链接',icon:Users}]
onMounted(async()=>{try{const data=await api('/api/me/renewal-plan');plan.value=data.plan}catch(e){error.value=(e as Error).message}})
</script>
<template>
 <section class="surface user-welcome"><div><span class="eyebrow">YOUR SPACE</span><h1>欢迎回来</h1><p class="muted">{{me.email}}</p></div><n-tag round :bordered="false" :type="expired?'warning':remaining>0?'success':'default'">{{expired?'套餐已到期':remaining>0?'服务使用中':'暂无可用流量'}}</n-tag></section>
 <n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert>
 <section class="user-stat-grid">
  <article class="surface user-metric"><span class="metric-symbol"><n-icon :component="Wallet" size="23"/></span><span class="muted">剩余流量</span><strong>{{bytes(remaining)}}</strong><small class="muted">本周期额度 {{bytes(me.quota_bytes)}}</small></article>
  <article class="surface user-metric"><span class="metric-symbol"><n-icon :component="Calendar" size="23"/></span><span class="muted">有效期</span><strong class="metric-date">{{me.expires_at?new Date(me.expires_at).toLocaleDateString('zh-CN'):'长期有效'}}</strong><small class="muted">{{expired?'续期后即可恢复服务':me.expires_at?'按账号有效期使用':'未设置到期时间'}}</small></article>
  <article class="surface user-metric"><span class="metric-symbol"><n-icon :component="Package" size="23"/></span><span class="muted">当前套餐</span><strong class="metric-plan">{{plan?.name||'尚未分配'}}</strong><small class="muted">{{plan?bytes(plan.quota_bytes)+' / '+plan.duration_days+' 天':'请联系管理员开通'}}</small></article>
 </section>
 <section class="surface service-overview"><div class="section-heading"><div><h2>我的服务</h2><p class="muted">流量与订阅，一目了然</p></div><n-button secondary size="small" @click="emit('navigate','orders')"><template #icon><n-icon :component="Receipt"/></template>续期与订单</n-button></div><div class="traffic-labels"><span>本周期已用 <strong>{{bytes(me.used_bytes)}}</strong></span><span class="muted">{{percentage.toFixed(1)}}%</span></div><n-progress type="line" :percentage="percentage" :show-indicator="false" :height="8" border-radius="8"/><div class="service-bottom"><span class="small muted">{{me.next_reset_at?'下次流量重置：'+cycleStamp(me.next_reset_at,zone):'尚未开通'}}</span><n-button type="primary" @click="emit('navigate','subscription')">查看我的订阅 <template #icon><n-icon :component="ArrowRight"/></template></n-button></div></section>
 <section class="user-shortcuts"><button v-for="item in shortcuts" :key="item.key" class="surface user-shortcut" @click="emit('navigate',item.key)"><span class="metric-symbol"><n-icon :component="item.icon" size="24"/></span><span><strong>{{item.title}}</strong><small class="muted">{{item.text}}</small></span><n-icon class="shortcut-arrow" :component="ArrowRight" size="18"/></button></section>
</template>
<style scoped>.user-welcome{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:22px;padding:24px 28px}.user-welcome h1{font-size:25px;margin:7px 0}.user-welcome p{margin:0;font-size:13px;overflow-wrap:anywhere}.user-stat-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-bottom:22px}.user-metric{position:relative;display:flex;align-items:flex-start;flex-direction:column;padding:24px 26px;gap:10px}.metric-symbol{display:flex;align-items:center;justify-content:center;width:48px;height:48px;flex:none;border-radius:14px;color:var(--green);background:var(--soft)}.user-metric>.metric-symbol{position:absolute;right:22px;top:23px}.user-metric>span.muted{font-size:12px}.user-metric>strong{font-size:28px;letter-spacing:-.7px;color:var(--text);padding-right:38px;overflow-wrap:anywhere}.user-metric>small{font-size:12px}.user-metric>.metric-date,.user-metric>.metric-plan{font-size:23px}.service-overview{padding:27px 28px;margin-bottom:22px}.service-overview .section-heading{margin-bottom:24px}.section-heading p{font-size:12px;margin:7px 0 0}.traffic-labels,.service-bottom{display:flex;align-items:center;justify-content:space-between;gap:16px}.traffic-labels{font-size:13px;margin-bottom:12px}.traffic-labels strong{margin-left:7px}.service-bottom{margin-top:23px}.user-shortcuts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.user-shortcut{text-align:left;display:flex;align-items:center;gap:16px;padding:21px 24px;transition:border-color .2s,transform .2s}.user-shortcut:hover{border-color:#90a7ed;transform:translateY(-2px)}.user-shortcut strong,.user-shortcut small{display:block}.user-shortcut strong{color:var(--text);font-size:15px}.user-shortcut small{font-size:12px;margin-top:6px}.shortcut-arrow{margin-left:auto;color:#94a5d7}@media(max-width:800px){.user-stat-grid{gap:12px}.user-metric{padding:20px}.user-metric>.metric-symbol{width:35px;height:35px;right:15px;top:17px}.user-metric>strong{font-size:23px}.user-metric>.metric-date,.user-metric>.metric-plan{font-size:20px}.user-shortcuts{gap:12px}.user-shortcut{padding:18px}.user-welcome,.service-overview{padding:22px}}@media(max-width:560px){.user-stat-grid{grid-template-columns:1fr}.user-metric{gap:6px}.user-metric>.metric-symbol{top:23px;right:22px;width:42px;height:42px}.user-shortcuts{grid-template-columns:1fr}.user-welcome{align-items:flex-start}.service-bottom{align-items:flex-start;flex-direction:column}.section-heading{align-items:flex-start;flex-direction:column}.user-welcome .eyebrow{font-size:9px}}
</style>
